constexpr int MAX_SIZE = 1024;

constexpr int square(int x) {
    return x * x;
}

// Result is computed at compile time
constexpr int area = square(12);

// Used in non-runtime context
int data[area];

// constexpr implies const for variables
// constexpr float PI = 3.14159f;

class Vector2D {
    const float x, y;
public:
    // C++11: Constructor must initialize members
    constexpr Vector2D(float vx, float vy) : x(vx), y(vy) {}

    constexpr float length_sq() const {
        return x * x + y * y;
    }
};

constexpr Vector2D v(3.0f, 4.0f);
constexpr float len2 = v.length_sq();

// C++14 Relaxation: Allows local mutable variables and loops
constexpr int factorial(int n) {
    int result = 1;
    for (int i = 2; i <= n; ++i) {
        result *= i;
    }
    return result;
}

constexpr int fact5 = factorial(5);
